import { Link } from "react-router-dom";
import React, { useEffect, useState } from "react";
import PropTypes from "prop-types";
import { getAllAgences, deleteAgenceById } from "../../services/ApiAgence";
import { confirmAlert } from 'react-confirm-alert';
import 'react-confirm-alert/src/react-confirm-alert.css';

export default function CardAgence({ color }) {
  const [agences, setAgences] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const getAgences = async () => {
    try {
      setLoading(true);
      const res = await getAllAgences();
      setAgences(res.data);
    } catch (error) {
      console.error("Error fetching agencies:", error);
      setError("Failed to load agencies. Please try again later.");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id) => {
    confirmAlert({
      title: 'Confirm Deletion',
      message: 'Are you sure you want to delete this agency?',
      buttons: [
        {
          label: 'Yes',
          onClick: async () => {
            try {
              await deleteAgenceById(id);
              getAgences();
            } catch (error) {
              console.error("Error deleting agency:", error);
              alert("Failed to delete agency. Please try again.");
            }
          }
        },
        {
          label: 'No',
          onClick: () => {}
        }
      ]
    });
  };

  useEffect(() => {
    getAgences();
  }, []);

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4" role="alert">
        <p>{error}</p>
        <button 
          onClick={getAgences}
          className="mt-2 bg-red-500 hover:bg-red-700 text-white font-bold py-1 px-2 rounded text-sm"
        >
          Retry
        </button>
      </div>
    );
  }

  return (
    <div className={`relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded ${
      color === "light" ? "bg-white" : "bg-lightBlue-900 text-white"
    }`}>
      <div className="rounded-t mb-0 px-4 py-3 border-0">
        <div className="flex flex-wrap items-center justify-between">
          <div className="relative px-4 max-w-full flex-grow flex-1">
            <h3 className={`font-semibold text-lg ${
              color === "light" ? "text-blueGray-700" : "text-white"
            }`}>
              Liste des Agences
            </h3>
          </div>
          <div>
            <Link 
              to="/admin/AddAgence" 
              className="bg-blue-500 hover:bg-blue-700 text-white font-semibold text-sm px-6 py-2 rounded-full shadow-md inline-flex items-center"
            >
              <span className="mr-1">+</span> Ajouter Agence
            </Link>
          </div>
        </div>
      </div>
      
      <div className="block w-full overflow-x-auto">
        {agences.length === 0 ? (
          <div className="p-6 text-center">
            <p className="text-gray-500">No agencies found</p>
          </div>
        ) : (
          <table className="items-center w-full bg-transparent border-collapse">
            <thead>
              <tr>
                {["Nom", "Ville", "Local", "Code Postal", "Actions"].map((header) => (
                  <th
                    key={header}
                    className={`px-6 align-middle border border-solid py-3 text-xs uppercase border-l-0 border-r-0 whitespace-nowrap font-semibold text-left ${
                      color === "light"
                        ? "bg-blueGray-50 text-blueGray-500 border-blueGray-100"
                        : "bg-lightBlue-800 text-lightBlue-300 border-lightBlue-700"
                    }`}
                  >
                    {header}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {agences.map((agence) => (
                <tr key={agence._id} className="hover:bg-gray-50 dark:hover:bg-lightBlue-800">
                  <td className="border-t-0 px-6 align-middle border-l-0 border-r-0 text-xs whitespace-nowrap p-4 text-left">
                    {agence.Nom}
                  </td>
                  <td className="border-t-0 px-6 align-middle border-l-0 border-r-0 text-xs whitespace-nowrap p-4">
                    {agence.ville}
                  </td>
                  <td className="border-t-0 px-6 align-middle border-l-0 border-r-0 text-xs whitespace-nowrap p-4">
                    {agence.local}
                  </td>
                  <td className="border-t-0 px-6 align-middle border-l-0 border-r-0 text-xs whitespace-nowrap p-4">
                    {agence.codePostal}
                  </td>
                  <td className="border-t-0 px-6 align-middle border-l-0 border-r-0 text-xs whitespace-nowrap p-4">
                    <div className="flex justify-center items-center gap-2">
                      <Link 
                        to={`/admin/update-agence/${agence._id}`}
                        className="bg-green-500 hover:bg-green-700 text-white font-semibold text-sm px-3 py-1 rounded-full shadow-md inline-flex items-center"
                      >
                        <span className="mr-1">✏️</span> Modifier
                      </Link>
                      <Link 
                        to={`/admin/AddAdmin/${agence._id}`}
                        className="bg-yellow-500 hover:bg-yellow-600 text-white font-semibold text-sm px-3 py-1 rounded-full shadow-md inline-flex items-center"
                      >
                        <span className="mr-1">👤</span> Admin
                      </Link>
                      <button 
                        onClick={() => handleDelete(agence._id)}
                        className="bg-red-500 hover:bg-red-700 text-white font-semibold text-sm px-3 py-1 rounded-full shadow-md inline-flex items-center"
                      >
                        <span className="mr-1">🗑️</span> Supprimer
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

CardAgence.defaultProps = {
  color: "light",
};

CardAgence.propTypes = {
  color: PropTypes.oneOf(["light", "dark"]),
};
